select public.assert_journey(not has_function_privilege('authenticated','public.claim_xooter_journey_email(text)','execute'),'ordinary user cannot claim email');
select public.assert_journey(not has_function_privilege('anon','public.xooter_email_worker_authorized()','execute'),'anonymous worker probe denied');
select public.assert_journey(not has_table_privilege('service_role','private.xooter_email_policy','update'),'worker cannot open or refill policy');
select private.start_xooter_journey('00000000-0000-4000-8000-000000000001');
select private.start_xooter_journey('00000000-0000-4000-8000-000000000002');
set role service_role;
select public.assert_journey(public.xooter_email_worker_authorized(),'actual worker database role');
select public.assert_journey(public.claim_xooter_journey_email('fxmxyabdjqviqbcxmvlp') is null,'closed sender consumes nothing');
reset role;
select public.assert_journey((select used=0 from private.xooter_email_policy),'closed quota intact');
update private.xooter_email_policy set enabled=true,project_ref='fxmxyabdjqviqbcxmvlp',allowed_user_ids=array['00000000-0000-4000-8000-000000000001'::uuid];
set role service_role;
select public.assert_journey(public.claim_xooter_journey_email('fxmxyabdjqviqbcxmvlp') is null,'no send without actual Free-plan review');
reset role;
update private.xooter_email_policy set free_plan_reviewed_at=clock_timestamp()-interval '8 days',free_plan_review_reference='SYNTHETIC EXPIRED REVIEW';
set role service_role;
select public.assert_journey(public.claim_xooter_journey_email('fxmxyabdjqviqbcxmvlp') is null,'expired Free review consumes no quota');
reset role;
select public.assert_journey((select used=0 from private.xooter_email_policy),'review refusal preserves quota');
update private.xooter_email_policy set free_plan_reviewed_at=clock_timestamp(),free_plan_review_reference='SYNTHETIC LOCAL REVIEW';
