select public.assert_journey(current_setting('xoot.local_claim')::jsonb ? 'nonce','one authorised claim');
select public.assert_journey(public.claim_xooter_journey_email('fxmxyabdjqviqbcxmvlp') is null,'one worker claim in flight');
select public.assert_journey(public.authorize_xooter_journey_email((current_setting('xoot.local_claim')::jsonb->>'id')::uuid,gen_random_uuid(),'fxmxyabdjqviqbcxmvlp') is null,'wrong nonce denied');
reset role;
update private.xooter_communication_preferences set email_updates=false where user_id='00000000-0000-4000-8000-000000000001';
