select public.assert_journey((select email_state='suppressed' from private.xooter_journey_events where user_id='00000000-0000-4000-8000-000000000001'),'revoked pending email suppressed');
select public.assert_journey((select used=1 from private.xooter_email_policy),'no consumed slot refund');
select public.assert_journey((select email_state='queued' from private.xooter_journey_events where user_id='00000000-0000-4000-8000-000000000002'),'allowlist leaves other recipient unclaimed');
update private.xooter_email_policy set allowed_user_ids=array['00000000-0000-4000-8000-000000000002'::uuid];
set role service_role;
select set_config('xoot.local_claim',public.claim_xooter_journey_email('fxmxyabdjqviqbcxmvlp')::text,false);
select public.expect_journey_error($$select public.finish_xooter_journey_email((current_setting('xoot.local_claim')::jsonb->>'id')::uuid,(current_setting('xoot.local_claim')::jsonb->>'nonce')::uuid,'accepted','synthetic-provider-message')$$,'22023');
select public.assert_journey(public.authorize_xooter_journey_email((current_setting('xoot.local_claim')::jsonb->>'id')::uuid,(current_setting('xoot.local_claim')::jsonb->>'nonce')::uuid,'fxmxyabdjqviqbcxmvlp')->>'email'='synthetic-two@example.test','recipient is current confirmed auth email');
select public.assert_journey(public.authorize_xooter_journey_email((current_setting('xoot.local_claim')::jsonb->>'id')::uuid,(current_setting('xoot.local_claim')::jsonb->>'nonce')::uuid,'fxmxyabdjqviqbcxmvlp') is null,'dispatch cannot be authorised twice');
select public.assert_journey(public.finish_xooter_journey_email((current_setting('xoot.local_claim')::jsonb->>'id')::uuid,(current_setting('xoot.local_claim')::jsonb->>'nonce')::uuid,'uncertain'),'ambiguous provider result is retained');
select public.assert_journey(not public.finish_xooter_journey_email((current_setting('xoot.local_claim')::jsonb->>'id')::uuid,(current_setting('xoot.local_claim')::jsonb->>'nonce')::uuid,'accepted','synthetic-provider-message'),'terminal uncertainty cannot be overwritten');
select public.assert_journey(public.claim_xooter_journey_email('fxmxyabdjqviqbcxmvlp') is null,'uncertain send is never automatically retried');
