select public.assert_journey((select used=2 from private.xooter_email_policy),'two actual claimed slots only');
select public.assert_journey((select email_state='suppressed' from private.xooter_journey_events where user_id='00000000-0000-4000-8000-000000000001'),'suppressed send stays terminal');
insert into public.xooter_applications(user_id,status) values('00000000-0000-4000-8000-000000000002','submitted');
set role service_role;
select set_config('xoot.local_claim',public.claim_xooter_journey_email('fxmxyabdjqviqbcxmvlp')::text,false);
reset role;
update public.xooter_applications set status='rejected';
set role service_role;
select public.assert_journey(public.authorize_xooter_journey_email((current_setting('xoot.local_claim')::jsonb->>'id')::uuid,(current_setting('xoot.local_claim')::jsonb->>'nonce')::uuid,'fxmxyabdjqviqbcxmvlp') is null,'stale submission mail suppressed after actual status change');
select set_config('xoot.local_claim',public.claim_xooter_journey_email('fxmxyabdjqviqbcxmvlp')::text,false);
select public.assert_journey(public.authorize_xooter_journey_email((current_setting('xoot.local_claim')::jsonb->>'id')::uuid,(current_setting('xoot.local_claim')::jsonb->>'nonce')::uuid,'fxmxyabdjqviqbcxmvlp')->>'kind'='xooter_application_attention','latest attention update can dispatch');
select public.assert_journey(public.finish_xooter_journey_email((current_setting('xoot.local_claim')::jsonb->>'id')::uuid,(current_setting('xoot.local_claim')::jsonb->>'nonce')::uuid,'accepted','synthetic-provider-message'),'acceptance recorded after actual dispatch authorization');
reset role;
select public.assert_journey((select count(*)=1 from private.xooter_journey_events where email_state='accepted'),'acceptance distinct from delivery');
select public.assert_journey(not exists(select from private.xooter_journey_events e join public.integration_outbox o on o.id=e.outbox_id where e.email_state='accepted' and (o.status<>'completed' or o.processed_at is null)),'accepted email uses the real completed outbox contract');
-- Re-entering a status must not resurrect a stale claimed or queued status email.
update public.xooter_applications set status='submitted';
set role service_role;
select set_config('xoot.local_claim',public.claim_xooter_journey_email('fxmxyabdjqviqbcxmvlp')::text,false);
reset role;
update public.xooter_applications set status='rejected';
update public.xooter_applications set status='submitted';
set role service_role;
select public.assert_journey(public.authorize_xooter_journey_email((current_setting('xoot.local_claim')::jsonb->>'id')::uuid,(current_setting('xoot.local_claim')::jsonb->>'nonce')::uuid,'fxmxyabdjqviqbcxmvlp') is null,'re-entered submitted status does not revive old claimed mail');
select set_config('xoot.local_claim',public.claim_xooter_journey_email('fxmxyabdjqviqbcxmvlp')::text,false);
select public.assert_journey(public.authorize_xooter_journey_email((current_setting('xoot.local_claim')::jsonb->>'id')::uuid,(current_setting('xoot.local_claim')::jsonb->>'nonce')::uuid,'fxmxyabdjqviqbcxmvlp')->>'kind'='xooter_application_received','latest resubmission alone can dispatch');
select public.assert_journey(public.finish_xooter_journey_email((current_setting('xoot.local_claim')::jsonb->>'id')::uuid,(current_setting('xoot.local_claim')::jsonb->>'nonce')::uuid,'accepted','synthetic-current-submitted'),'latest submitted receipt records acceptance');
reset role;
-- A claim returns as soon as it finds one eligible row. Transaction timestamps can tie,
-- so older status rows may sort after it; a stale-only scan must drain without spending.
select set_config('xoot.stale_scan_used',(select used::text from private.xooter_email_policy where id),false);
set role service_role;
select public.assert_journey(public.claim_xooter_journey_email('fxmxyabdjqviqbcxmvlp') is null,'stale attention queue cannot produce another claim');
reset role;
select public.assert_journey((select used=current_setting('xoot.stale_scan_used')::integer from private.xooter_email_policy where id),'stale attention scan consumes no quota');
select public.assert_journey((select email_state='suppressed' from private.xooter_journey_events where event_key='status:3'),'old submitted claim is terminal');
select public.assert_journey((select email_state='suppressed' from private.xooter_journey_events where event_key='status:4'),'intermediate attention queue is suppressed');
update public.xooter_applications set status='rejected';
set role service_role;
select set_config('xoot.local_claim',public.claim_xooter_journey_email('fxmxyabdjqviqbcxmvlp')::text,false);
reset role;
update public.xooter_applications set status='submitted';
update public.xooter_applications set status='rejected';
